package jp.reader.manga;

import android.app.*;
import android.os.*;
import android.security.KeyChain;
import android.content.*;
import android.graphics.Bitmap;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
  android.content.SharedPreferences prefs; ExecutorService worker=Executors.newSingleThreadExecutor(); Handler ui=new Handler(Looper.getMainLooper()); int generation=0; LinearLayout root; Dav dav; RemoteZip zip; String bookUrl,bookName,folderUrl,folderName; int page=0,next=0; boolean reading=false; HashMap<Integer,Integer> previous=new HashMap<>(); TreeSet<Integer> cuts=new TreeSet<>(); Bitmap right,left; String alias="";
  interface Task<T>{T run() throws Exception;} interface Done<T>{void accept(T x) throws Exception;}
  public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("reader",MODE_PRIVATE);alias=prefs.getString("alias","");home();}
  void clear(){ generation++; root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfffafafa);setContentView(root); }
  TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(0xff111111);v.setPadding(16,12,16,12);return v;}
  Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
  LinearLayout scroll(){ScrollView sv=new ScrollView(this);LinearLayout l=new LinearLayout(this);l.setOrientation(1);sv.addView(l);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));return l;}
  void message(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  <T> void async(Task<T> task,Done<T> done){int id=generation;worker.execute(()->{try{T result=task.run();ui.post(()->{if(id!=generation){if(result instanceof Spread){Spread discarded=(Spread)result;discarded.a.recycle();if(discarded.b!=null)discarded.b.recycle();}return;}try{done.accept(result);}catch(Exception e){message(e.toString());}});}catch(Exception e){ui.post(()->{if(id==generation)message("エラー: "+e.getMessage());});}});}
  JSONObject records(){try{return new JSONObject(prefs.getString("records","{}"));}catch(Exception e){return new JSONObject();}}
  void put(String key,JSONObject value){try{JSONObject all=records();all.put(key,value);prefs.edit().putString("records",all.toString()).apply();}catch(Exception e){message(e.toString());}}
  JSONObject record(String key){JSONObject j=records().optJSONObject(key);return j==null?new JSONObject():j;}
  String clean(String s){return s.replaceFirst("^\\s*\\([^)]*\\)\\s*","").replaceFirst("^\\s*\\[[^]]*\\]\\s*","").replaceFirst("(?i)\\.(zip|cbz)$","").trim();}
  String author(String s){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\[([^]]+)\\]").matcher(s);return m.find()?m.group(1):"";}
  void home(){reading=false;zip=null;release();clear();root.addView(text("漫画リーダー",25));LinearLayout bar=new LinearLayout(this);bar.addView(button("フォルダ",()->browse(prefs.getString("url",""),"フォルダ")));bar.addView(button("接続設定",this::settings));root.addView(bar);LinearLayout list=scroll();JSONObject all=records();ArrayList<JSONObject> recent=new ArrayList<>();Iterator<String> keys=all.keys();while(keys.hasNext()){JSONObject o=all.optJSONObject(keys.next());if(o!=null&&!o.optBoolean("finished"))recent.add(o);}recent.sort((a,b)->Long.compare(b.optLong("time"),a.optLong("time")));
    list.addView(text("最近読んだ本",21));if(recent.isEmpty())list.addView(text("読みかけの本はありません",14));for(JSONObject o:recent){String name=o.optString("name"),url=o.optString("url"),fu=o.optString("folder"),fn=o.optString("folderName");TextView v=text(clean(name)+"\n"+author(name)+"  途中 "+(o.optInt("page")+1)+" / "+o.optInt("total"),18);list.addView(v);v.setOnClickListener(w->openBook(url,name,fu,fn));}
    list.addView(text("読みかけのシリーズ",21));HashSet<String> seen=new HashSet<>();ArrayList<JSONObject> series=new ArrayList<>();for(JSONObject o:recent)if(seen.add(o.optString("folder")))series.add(o);
    String sort=prefs.getString("sort","最近読んだ順");if(sort.equals("タイトル順"))series.sort((a,b)->RemoteZip.natural(clean(a.optString("folderName")),clean(b.optString("folderName"))));else if(sort.equals("著者順"))series.sort((a,b)->RemoteZip.natural(author(a.optString("folderName")),author(b.optString("folderName"))));
    list.addView(button("並び替え: "+sort,()->new AlertDialog.Builder(this).setTitle("並び替え").setItems(new String[]{"最近読んだ順","タイトル順","著者順"},(d,n)->{prefs.edit().putString("sort",new String[]{"最近読んだ順","タイトル順","著者順"}[n]).apply();home();}).show()));
    for(JSONObject o:series){String fn=o.optString("folderName"),fu=o.optString("folder"),bn=o.optString("name");TextView v=text(clean(fn)+"\n"+author(fn)+"\n"+clean(bn)+"  途中 "+(o.optInt("page")+1)+" / "+o.optInt("total"),18);list.addView(v);v.setOnClickListener(w->browse(fu,fn));}
  }
  void settings(){clear();root.addView(button("← ホーム",this::home));root.addView(text("WebDAV接続設定",23));LinearLayout l=scroll();EditText u=new EditText(this),n=new EditText(this),p=new EditText(this);u.setHint("https://example.com/webdav/");u.setSingleLine();u.setText(prefs.getString("url",""));n.setHint("ユーザー名（必要な場合）");n.setText(prefs.getString("user",""));p.setHint("パスワード（端末内に保存）");p.setInputType(129);p.setText(prefs.getString("pass",""));l.addView(u);l.addView(n);l.addView(p);TextView cert=text("証明書: "+(alias.isEmpty()?"未選択":alias),15);l.addView(cert);l.addView(button("証明書を選択",()->KeyChain.choosePrivateKeyAlias(this,a->{if(a!=null){alias=a;ui.post(()->cert.setText("証明書: "+a));}},null,null,null,-1,alias.isEmpty()?null:alias)));l.addView(button("証明書を解除",()->{alias="";cert.setText("証明書: 未選択");}));l.addView(text("PKCS#12証明書は事前にAndroidの設定からインストールしてください。パスワードはアプリ専用領域に保存します。",14));l.addView(button("保存",()->{String url=u.getText().toString().trim();if(!url.startsWith("https://")){message("HTTPSのURLを入力してください");return;}if(!url.endsWith("/"))url+="/";prefs.edit().putString("url",url).putString("user",n.getText().toString()).putString("pass",p.getText().toString()).putString("alias",alias).apply();home();}));}
  Dav client() throws Exception{return new Dav(this,prefs.getString("url",""),prefs.getString("user",""),prefs.getString("pass",""),prefs.getString("alias",""));}
  void browse(String url,String name){if(url.isEmpty()){settings();return;}reading=false;release();clear();root.addView(button("← ホーム",this::home));root.addView(text(clean(name),23));LinearLayout list=scroll();TextView status=text("読み込み中…",16);list.addView(status);async(()->{Dav d=client();return d.list(url);},items->{list.removeView(status);items.sort((a,b)->a.dir!=b.dir?(a.dir?-1:1):RemoteZip.natural(a.name,b.name));for(Dav.Item item:items){JSONObject rec=record(item.url);String sub=item.dir?"フォルダ":rec.length()==0?"未読":rec.optBoolean("finished")?"既読":"途中  "+(rec.optInt("page")+1)+" / "+rec.optInt("total");TextView v=text(clean(item.name)+"\n"+author(item.name)+"  "+sub,18);list.addView(v);v.setOnClickListener(w->{if(item.dir)browse(item.url,item.name);else openBook(item.url,item.name,url,name);});}if(items.isEmpty())list.addView(text("フォルダまたはZIPがありません",16));});}
  void openBook(String url,String name,String folder,String fname){bookUrl=url;bookName=name;folderUrl=folder;folderName=fname;reading=true;previous.clear();cuts.clear();JSONObject rec=record(url);page=rec.optInt("page",0);JSONArray arr=rec.optJSONArray("cuts");if(arr!=null)for(int i=0;i<arr.length();i++)cuts.add(arr.optInt(i));clear();root.addView(button("← ホーム",this::home));root.addView(text("本を開いています…",20));async(()->{Dav d=client();return new RemoteZip(d,url);},z->{zip=z;page=Math.max(0,Math.min(page,zip.pages.size()-1));render();});}
  void save(){if(zip==null)return;JSONObject o=record(bookUrl);try{o.put("url",bookUrl);o.put("name",bookName);o.put("folder",folderUrl);o.put("folderName",folderName);o.put("page",page);o.put("total",zip.pages.size());o.put("time",System.currentTimeMillis());o.put("finished",next>=zip.pages.size());JSONArray a=new JSONArray();for(int cut:cuts)a.put(cut);o.put("cuts",a);put(bookUrl,o);}catch(Exception ignored){}}
  void release(){if(right!=null){right.recycle();right=null;}if(left!=null){left.recycle();left=null;}}
  static final class Spread {Bitmap a,b;int next;Spread(Bitmap x,Bitmap y,int n){a=x;b=y;next=n;}}
  void render(){if(zip==null)return;clear();release();LinearLayout bar=new LinearLayout(this);bar.addView(button("← ホーム",this::home));bar.addView(button("見開き調整",()->new AlertDialog.Builder(this).setTitle("見開き調整").setItems(new String[]{"このページの次から1ページずらす","この本の調整をすべて解除"},(d,n)->{if(n==0 && page+1<zip.pages.size())cuts.add(page+1);else if(n==1)cuts.clear();previous.clear();render();}).show()));bar.addView(button("前へ",this::backPage));bar.addView(button("次へ",this::forward));root.addView(bar);TextView status=text("読み込み中…",14);root.addView(status);LinearLayout images=new LinearLayout(this);images.setGravity(Gravity.CENTER);root.addView(images,new LinearLayout.LayoutParams(-1,0,1));final int requested=page;final RemoteZip current=zip;final TreeSet<Integer> anchors=new TreeSet<>(cuts);int width=getResources().getDisplayMetrics().widthPixels,height=getResources().getDisplayMetrics().heightPixels;
    async(()->{Bitmap a=current.bitmap(requested,width,height);Bitmap b=null;int n=requested+1;if(a.getWidth()<a.getHeight()&&n<current.pages.size()&&!anchors.contains(n)){try{b=current.bitmap(n,width,height);}catch(Exception e){a.recycle();throw e;}if(b.getWidth()<b.getHeight())n++;else{b.recycle();b=null;}}return new Spread(a,b,n);},s->{release();right=s.a;left=s.b;next=s.next;status.setText((page+1)+(next>page+1?"–"+next:"")+" / "+zip.pages.size());if(left!=null){ImageView lv=new ImageView(this);lv.setImageBitmap(left);lv.setScaleType(ImageView.ScaleType.FIT_CENTER);images.addView(lv,new LinearLayout.LayoutParams(0,-1,1));}ImageView rv=new ImageView(this);rv.setImageBitmap(right);rv.setScaleType(ImageView.ScaleType.FIT_CENTER);images.addView(rv,new LinearLayout.LayoutParams(0,-1,1));images.setOnTouchListener(new View.OnTouchListener(){float x;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getX();return true;}if(e.getAction()==1){float delta=e.getX()-x;if(Math.abs(delta)>70){if(delta>0)forward();else backPage();}else if(e.getX()<v.getWidth()/2f)forward();else backPage();return true;}return true;}});save();});
  }
  void forward(){if(zip==null||next<=page||next>=zip.pages.size())return;previous.put(next,page);page=next;next=0;render();}
  void backPage(){if(zip==null||page<=0)return;Integer p=previous.get(page);page=p!=null?p:Math.max(0,page-2);next=0;render();}
  @Override public void onBackPressed(){if(reading)home();else home();}
  @Override protected void onDestroy(){generation++;worker.shutdownNow();release();super.onDestroy();}
}
